#!/usr/bin/env bash
# Milestone 1: cross-build ROCm 6.3.3 ROCR Runtime + rocminfo for Ubuntu Noble
# ARM64 from an x86_64 Linux host. AMDGPU assembly is generated by host Clang.
# This is a build/ABI proof of concept, not a full ROCm/PyTorch payload builder.
set -euo pipefail

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd -- "$SCRIPT_DIR/.." && pwd)
ROCM_VER=${ROCM_VER:-6.3.3}
TAG="rocm-$ROCM_VER"
WORK_ROOT=${WORK_ROOT:-${XDG_CACHE_HOME:-$HOME/.cache}/mi50-arm64-cross}
CROSS_COMPILER=${CROSS_COMPILER:-clang} # clang | gcc
JOBS=${JOBS:-$(nproc)}
LLVM_JOBS=${LLVM_JOBS:-$(( JOBS > 4 ? 4 : JOBS ))}
LINK_JOBS=${LINK_JOBS:-1}
SYSROOT_TAR=${SYSROOT_TAR:-}
SYSROOT_SOURCE_IMG=${SYSROOT_SOURCE_IMG:-}
REQUIRE_MOUNT_POINT=${REQUIRE_MOUNT_POINT:-}
REQUIRED_MOUNT_FSTYPE=${REQUIRED_MOUNT_FSTYPE:-}
SKIP_QEMU_SMOKE=${SKIP_QEMU_SMOKE:-0}

SYSROOT="$WORK_ROOT/sysroot"
SRC="$WORK_ROOT/sources"
BLD="$WORK_ROOT/builds"
TOOLCHAIN_DIR="$WORK_ROOT/toolchain"
HOST_ROCM="$WORK_ROOT/host-rocm"
HOST_LLVM="$HOST_ROCM/llvm"
HOST_VENV="$WORK_ROOT/host-venv"
TARGET_ROCM="$WORK_ROOT/target-rocm"
DOWNLOADS="$WORK_ROOT/downloads"
STAGES=(preflight sysroot toolchain host_venv fetch rocm_cmake host_llvm device_libs rocr rocminfo verify)
STAGING_SYSROOT=""

log() { printf '\n[mi50-cross] %s\n' "$*"; }
die() { printf '[mi50-cross] ERROR: %s\n' "$*" >&2; exit 1; }

usage() {
  cat <<USAGE
Usage: $(basename "$0") [--list | --only STAGE | START_STAGE]

Stages: ${STAGES[*]}

Environment:
  WORK_ROOT                 Workspace root (default: ~/.cache/mi50-arm64-cross)
  CROSS_COMPILER            clang (default) or gcc
  ROCM_VER                  ROCm source tag version (default: 6.3.3)
  SYSROOT_TAR               Optional prebuilt Noble ARM64 sysroot tar archive
  SYSROOT_SOURCE_IMG        Optional read-only Noble ARM64 .img to copy and complete with -dev .debs
  REQUIRE_MOUNT_POINT       Optional exact mountpoint required for WORK_ROOT
  REQUIRED_MOUNT_FSTYPE     Optional filesystem type required (e.g. ext4)
  SKIP_QEMU_SMOKE=1          Skip QEMU execution test (ELF checks still run)
  JOBS                      Parallel build jobs (default: nproc)
USAGE
}

nearest_existing_dir() {
  local p=$1
  while [ ! -e "$p" ] && [ "$p" != / ]; do p=$(dirname "$p"); done
  printf '%s\n' "$p"
}

ensure_work_root_safe() {
  local probe info target fstype opts
  probe=$(nearest_existing_dir "$WORK_ROOT")
  [ -d "$probe" ] || die "No existing parent directory for WORK_ROOT=$WORK_ROOT"
  info=$(findmnt -T "$probe" -n -o TARGET,FSTYPE,OPTIONS) || die "findmnt failed for $probe"
  read -r target fstype opts <<<"$info"
  case ",$opts," in *,rw,*) ;; *) die "Filesystem $target ($fstype) is not mounted read-write: $opts" ;; esac
  case "$WORK_ROOT" in
    /run/media/*|/mnt/*)
      [ "$target" != / ] || die "External workspace path resolves to /; expected volume is not mounted"
      ;;
  esac
  if [ -n "$REQUIRE_MOUNT_POINT" ] && [ "$target" != "$REQUIRE_MOUNT_POINT" ]; then
    die "WORK_ROOT is on '$target', expected '$REQUIRE_MOUNT_POINT'"
  fi
  if [ -n "$REQUIRED_MOUNT_FSTYPE" ] && [ "$fstype" != "$REQUIRED_MOUNT_FSTYPE" ]; then
    die "WORK_ROOT filesystem is '$fstype', expected '$REQUIRED_MOUNT_FSTYPE'"
  fi
  mkdir -p "$SRC" "$BLD" "$TOOLCHAIN_DIR" "$HOST_ROCM" "$TARGET_ROCM" "$DOWNLOADS"
  log "Workspace verified: $WORK_ROOT (mount=$target, type=$fstype, rw)"
}

find_qemu() {
  command -v qemu-aarch64-static 2>/dev/null || command -v qemu-aarch64 2>/dev/null || return 1
}

stage_preflight() {
  [ "$(uname -m)" = x86_64 ] || die "Expected x86_64 host; found $(uname -m)"
  local cmd
  for cmd in cmake ninja git python3 pkg-config readelf findmnt tar patch; do
    command -v "$cmd" >/dev/null 2>&1 || die "Missing host tool: $cmd"
  done
  command -v clang >/dev/null 2>&1 || die "Host clang is required for AMDGPU shader assembly"
  command -v llvm-objcopy >/dev/null 2>&1 || die "Host llvm-objcopy is required for shader extraction"
  command -v llvm-strip >/dev/null 2>&1 || die "Host llvm-strip is required for cross-built Release stripping"
  clang --print-targets 2>/dev/null | grep -qi amdgpu || die "Host clang has no AMDGPU backend"
  printf '.text\n' | clang -x assembler -target amdgcn-amd-amdhsa -mcpu=gfx906 -c - -o /dev/null \
    || die "Host clang cannot assemble gfx906 AMDGPU input"

  case "$CROSS_COMPILER" in
    clang)
      command -v clang++ >/dev/null 2>&1 || die "Missing clang++"
      command -v ld.lld >/dev/null 2>&1 || die "Missing ld.lld (Clang -fuse-ld=lld needs this executable)"
      printf 'int f(void) { return 0; }\n' | clang --target=aarch64-linux-gnu -x c -c - -o /dev/null \
        || die "Host clang has no working AArch64 backend"
      ;;
    gcc)
      command -v aarch64-linux-gnu-gcc >/dev/null 2>&1 || die "Missing aarch64-linux-gnu-gcc"
      command -v aarch64-linux-gnu-g++ >/dev/null 2>&1 || die "Missing aarch64-linux-gnu-g++"
      ;;
    *) die "CROSS_COMPILER must be clang or gcc" ;;
  esac

  if [ ! -f "$SYSROOT/.mi50-sysroot-complete" ]; then
    if [ -n "$SYSROOT_SOURCE_IMG" ]; then
      [ -f "$SYSROOT_SOURCE_IMG" ] || die "SYSROOT_SOURCE_IMG not found: $SYSROOT_SOURCE_IMG"
      for cmd in rsync losetup mount umount mountpoint sudo ar; do
        command -v "$cmd" >/dev/null 2>&1 || die "SYSROOT_SOURCE_IMG mode requires host tool: $cmd"
      done
    elif [ -z "$SYSROOT_TAR" ] && ! command -v mmdebstrap >/dev/null 2>&1 && ! command -v debootstrap >/dev/null 2>&1; then
      die "Provide SYSROOT_SOURCE_IMG, SYSROOT_TAR, mmdebstrap, or debootstrap"
    fi
  fi
  if [ "$SKIP_QEMU_SMOKE" != 1 ]; then
    find_qemu >/dev/null || die "Install qemu-user (qemu-aarch64 or qemu-aarch64-static), or set SKIP_QEMU_SMOKE=1"
  fi
  ensure_work_root_safe
}

verify_sysroot_contents() {
  local root=$1 rel
  for rel in \
    etc/os-release \
    usr/include/aarch64-linux-gnu/gnu/stubs.h \
    usr/include/libelf.h \
    usr/include/numa.h \
    usr/include/c++/13/vector \
    usr/lib/gcc/aarch64-linux-gnu/13/crtbeginS.o \
    usr/lib/aarch64-linux-gnu/pkgconfig/libdrm.pc \
    usr/lib/aarch64-linux-gnu/pkgconfig/libdrm_amdgpu.pc; do
    [ -e "$root/$rel" ] || die "Sysroot is missing $rel"
  done
  grep -q 'VERSION_CODENAME=noble' "$root/etc/os-release" || die "Sysroot is not Ubuntu Noble"
  [ -d "$root/usr/lib/gcc/aarch64-linux-gnu/13" ] || die "Noble GCC 13 runtime directory missing"
}

normalize_sysroot_symlinks() {
  python3 - "$1" <<'PY'
import os, sys
root = os.path.abspath(sys.argv[1])
count = 0
for directory, dirs, files in os.walk(root, followlinks=False):
    for name in list(dirs) + list(files):
        path = os.path.join(directory, name)
        if not os.path.islink(path):
            continue
        target = os.readlink(path)
        if target.startswith('/'):
            relative = os.path.relpath(os.path.join(root, target.lstrip('/')), directory)
            os.unlink(path)
            os.symlink(relative, path)
            count += 1
print(f"Normalized {count} absolute sysroot symlinks")
PY
}

install_noble_deb_overlays() {
  local staging=$1 deb_cache="$DOWNLOADS/noble-arm64-debs"
  mkdir -p "$deb_cache"
  python3 - "$staging" "$deb_cache" <<'PY_DEB'
import hashlib, lzma, os, subprocess, sys, urllib.request

staging = os.path.abspath(sys.argv[1])
cache = os.path.abspath(sys.argv[2])
base = "http://ports.ubuntu.com/ubuntu-ports"
suites = ("noble-updates", "noble")
wanted = [
    "libdrm-dev", "libdrm2", "libdrm-amdgpu1", "libdrm-common",
    "libpciaccess-dev", "libpciaccess0",
    "libelf-dev", "libelf1t64",
    "libnuma-dev", "libnuma1",
    "libzstd-dev", "libzstd1",
]

index = {}
for suite in suites:
    pkg_idx = os.path.join(cache, f"{suite}-main-arm64-Packages.xz")
    url = f"{base}/dists/{suite}/main/binary-arm64/Packages.xz"
    if not os.path.isfile(pkg_idx):
        print(f"[mi50-cross] Fetching package index: {url}")
        urllib.request.urlretrieve(url, pkg_idx)
    raw = lzma.decompress(open(pkg_idx, "rb").read()).decode("utf-8", "replace")
    for block in raw.split("\n\n"):
        meta = {}
        for line in block.splitlines():
            if ": " in line and not line.startswith(" "):
                k, v = line.split(": ", 1)
                meta[k] = v
        pkg = meta.get("Package")
        if pkg in wanted and pkg not in index:
            index[pkg] = meta

missing = [p for p in wanted if p not in index]
if missing:
    raise SystemExit(f"Could not find Noble ARM64 packages: {missing}")

for pkg in wanted:
    meta = index[pkg]
    rel = meta["Filename"]
    sha = meta["SHA256"]
    deb_path = os.path.join(cache, os.path.basename(rel))
    if not os.path.isfile(deb_path) or hashlib.sha256(open(deb_path, "rb").read()).hexdigest() != sha:
        deb_url = f"{base}/{rel}"
        print(f"[mi50-cross] Downloading {pkg} ({meta['Version']})")
        urllib.request.urlretrieve(deb_url, deb_path)
        got = hashlib.sha256(open(deb_path, "rb").read()).hexdigest()
        if got != sha:
            raise SystemExit(f"SHA-256 mismatch for {deb_path}: expected {sha}, got {got}")

    members = subprocess.check_output(["ar", "t", deb_path], text=True).splitlines()
    data_member = next((m for m in members if m.startswith("data.tar")), None)
    if data_member is None:
        raise SystemExit(f"No data.tar member in {deb_path}: {members}")
    comp_flag = {
        ".zst": "--zstd",
        ".xz": "--xz",
        ".gz": "--gzip",
        ".bz2": "--bzip2",
    }.get(os.path.splitext(data_member)[1], "")
    ar_proc = subprocess.Popen(["ar", "p", deb_path, data_member], stdout=subprocess.PIPE)
    tar_cmd = ["tar", "--no-same-owner", "-xf", "-", "--keep-directory-symlink"]
    if comp_flag:
        tar_cmd.append(comp_flag)
    tar_cmd.extend(["-C", staging])
    rc = subprocess.run(tar_cmd, stdin=ar_proc.stdout).returncode
    ar_rc = ar_proc.wait()
    if rc != 0 or ar_rc != 0:
        raise SystemExit(f"Failed extracting {deb_path} ({data_member}): ar={ar_rc}, tar={rc}")
print(f"Extracted {len(wanted)} Noble ARM64 runtime/dev packages cleanly")
PY_DEB
}

stage_sysroot() {
  log "Preparing Ubuntu Noble ARM64 sysroot"
  ensure_work_root_safe
  if [ -f "$SYSROOT/.mi50-sysroot-complete" ]; then
    verify_sysroot_contents "$SYSROOT"
    log "Reusing complete sysroot at $SYSROOT"
    return
  fi
  if [ -e "$SYSROOT" ] && [ -n "$(find "$SYSROOT" -mindepth 1 -maxdepth 1 -print -quit 2>/dev/null)" ]; then
    die "Existing incomplete sysroot at $SYSROOT; refusing to delete or overwrite it. Inspect it and move it aside manually."
  fi

  local pkgs staging tarball
  pkgs="libc6,libc6-dev,libstdc++6,libstdc++-13-dev,libgcc-13-dev,libdrm2,libdrm-amdgpu1,libdrm-dev,libelf1t64,libelf-dev,libnuma1,libnuma-dev,zlib1g-dev,libzstd-dev,pkg-config"
  staging="$WORK_ROOT/sysroot.staging.$$"
  [ ! -e "$staging" ] || die "Staging path already exists: $staging; inspect it manually"
  mkdir -p "$staging"
  STAGING_SYSROOT="$staging"

  if [ -n "$SYSROOT_SOURCE_IMG" ]; then
    [ -f "$SYSROOT_SOURCE_IMG" ] || die "SYSROOT_SOURCE_IMG does not exist: $SYSROOT_SOURCE_IMG"
    log "Copying read-only ARM64 rootfs from $SYSROOT_SOURCE_IMG"
    (
      mnt=$(mktemp -d /tmp/mi50-sysroot-img.XXXXXX)
      loop=""
      cleanup_img() {
        set +e
        if [ -n "$mnt" ] && mountpoint -q "$mnt"; then sudo umount "$mnt"; fi
        if [ -n "$loop" ]; then sudo losetup -d "$loop"; fi
        if [ -n "$mnt" ] && [ -d "$mnt" ]; then rmdir "$mnt"; fi
      }
      trap cleanup_img EXIT
      loop=$(sudo losetup --find --show --read-only --partscan "$SYSROOT_SOURCE_IMG")
      sudo mount -t ext4 -o ro,noload "${loop}p1" "$mnt"
      sudo rsync -aH --numeric-ids \
        --exclude='/dev/*' --exclude='/proc/*' --exclude='/sys/*' \
        --exclude='/run/*' --exclude='/tmp/*' --exclude='/lost+found' \
        --exclude='/home/*' --exclude='/root/*' \
        "$mnt/" "$staging/"
    )
    sudo chown -R "$(id -u):$(id -g)" "$staging"
    install_noble_deb_overlays "$staging"
  elif [ -n "$SYSROOT_TAR" ]; then
    [ -f "$SYSROOT_TAR" ] || die "SYSROOT_TAR does not exist: $SYSROOT_TAR"
    tar --no-same-owner -xf "$SYSROOT_TAR" -C "$staging"
  elif command -v mmdebstrap >/dev/null 2>&1; then
    tarball="$DOWNLOADS/noble-arm64-sysroot.$$.tar"
    mmdebstrap --mode=unshare --arch=arm64 --variant=apt \
      --components=main,universe --include="$pkgs" \
      noble "$tarball" http://ports.ubuntu.com/ubuntu-ports
    tar --no-same-owner -xf "$tarball" -C "$staging"
    rm -f "$tarball"
  else
    grep -rqE '7f454c4602010100.*b700' /proc/sys/fs/binfmt_misc/ 2>/dev/null \
      || die "debootstrap fallback requires a registered aarch64 binfmt_misc handler (or use SYSROOT_SOURCE_IMG)"
    command -v qemu-aarch64-static >/dev/null 2>&1 || die "debootstrap fallback requires qemu-aarch64-static"
    command -v sudo >/dev/null 2>&1 || die "debootstrap fallback requires sudo"
    sudo debootstrap --arch=arm64 --foreign --variant=minbase --components=main,universe \
      noble "$staging" http://ports.ubuntu.com/ubuntu-ports
    sudo install -m 0755 "$(command -v qemu-aarch64-static)" "$staging/usr/bin/qemu-aarch64-static"
    sudo chroot "$staging" /debootstrap/debootstrap --second-stage
    sudo chroot "$staging" env DEBIAN_FRONTEND=noninteractive apt-get update
    sudo chroot "$staging" env DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends \
      libc6-dev libstdc++-13-dev libgcc-13-dev libdrm-dev libelf-dev libnuma-dev zlib1g-dev libzstd-dev pkg-config
    sudo chown -R "$(id -u):$(id -g)" "$staging"
  fi

  chmod -R u+rwX "$staging"
  normalize_sysroot_symlinks "$staging"
  verify_sysroot_contents "$staging"
  printf 'noble-arm64-gcc13\n' > "$staging/.mi50-sysroot-complete"
  if [ -d "$SYSROOT" ]; then rmdir "$SYSROOT"; fi
  mv "$staging" "$SYSROOT"
  STAGING_SYSROOT=""
  log "Sysroot ready: $SYSROOT"
}

stage_toolchain() {
  log "Creating isolated cross toolchain and host LLVM package shims"
  ensure_work_root_safe
  verify_sysroot_contents "$SYSROOT"
  local shim_dir tc_file host_clang host_clangxx host_objcopy host_strip gcc_dir llvm_ver
  shim_dir="$TOOLCHAIN_DIR/host-llvm-cmake"
  mkdir -p "$shim_dir"
  host_clang=$(command -v clang)
  host_clangxx=$(command -v clang++)
  host_objcopy=$(command -v llvm-objcopy)
  host_strip=$(command -v llvm-strip)
  llvm_ver=23.1.5
  if command -v llvm-config >/dev/null 2>&1; then llvm_ver=$(llvm-config --version); fi

  cat > "$shim_dir/LLVMConfig.cmake" <<EOF_CMAKE
# Minimal host-tool shim. ROCR Runtime only needs imported clang and llvm-objcopy executables.
set(LLVM_FOUND TRUE)
set(LLVM_VERSION "$llvm_ver")
set(LLVM_PACKAGE_VERSION "$llvm_ver")
if(NOT TARGET llvm-objcopy)
  add_executable(llvm-objcopy IMPORTED GLOBAL)
  set_target_properties(llvm-objcopy PROPERTIES IMPORTED_LOCATION "$host_objcopy")
endif()
EOF_CMAKE
  local asm_clang="$host_clang"
  if ! printf '.text\n' | "$host_clang" -x assembler -target amdgcn-amd-amdhsa -mcpu=gfx940 -c - -o /dev/null >/dev/null 2>&1; then
    asm_clang="$shim_dir/amdgpu-asm-clang"
    cat > "$asm_clang" <<EOF_WRAP
#!/usr/bin/env bash
args=()
for a in "\$@"; do
  case "\$a" in
    -mcpu=gfx940|-mcpu=gfx941) args+=("-mcpu=gfx942") ;;
    *) args+=("\$a") ;;
  esac
done
exec "$host_clang" "\${args[@]}"
EOF_WRAP
    chmod +x "$asm_clang"
  fi
  cat > "$shim_dir/ClangConfig.cmake" <<EOF_CMAKE
# Minimal host-tool shim. No Arch LLVM library or include paths are imported.
set(Clang_FOUND TRUE)
set(CLANG_FOUND TRUE)
if(NOT TARGET clang)
  add_executable(clang IMPORTED GLOBAL)
  set_target_properties(clang PROPERTIES IMPORTED_LOCATION "$asm_clang")
endif()
EOF_CMAKE

  gcc_dir="$SYSROOT/usr/lib/gcc/aarch64-linux-gnu/13"
  [ -d "$gcc_dir" ] || die "Missing Noble GCC 13 installation: $gcc_dir"
  tc_file="$TOOLCHAIN_DIR/aarch64-noble-toolchain.cmake"
  cat > "$tc_file" <<EOF_CMAKE
set(CMAKE_SYSTEM_NAME Linux)
set(CMAKE_SYSTEM_PROCESSOR aarch64)
set(CMAKE_SYSROOT "$SYSROOT")
set(CMAKE_FIND_ROOT_PATH "$SYSROOT" "$TARGET_ROCM" "$TOOLCHAIN_DIR")
set(CMAKE_FIND_ROOT_PATH_MODE_PROGRAM NEVER)
set(CMAKE_FIND_ROOT_PATH_MODE_LIBRARY ONLY)
set(CMAKE_FIND_ROOT_PATH_MODE_INCLUDE ONLY)
set(CMAKE_FIND_ROOT_PATH_MODE_PACKAGE ONLY)

set(ENV{PKG_CONFIG_PATH} "")
set(ENV{PKG_CONFIG_DIR} "")
set(ENV{PKG_CONFIG_LIBDIR} "$SYSROOT/usr/lib/aarch64-linux-gnu/pkgconfig:$SYSROOT/usr/share/pkgconfig:$SYSROOT/usr/lib/pkgconfig")
set(ENV{PKG_CONFIG_SYSROOT_DIR} "$SYSROOT")
set(PKG_CONFIG_EXECUTABLE "/usr/bin/pkg-config" CACHE FILEPATH "Host pkg-config with Noble-only search paths" FORCE)

set(CMAKE_STRIP "$host_strip" CACHE FILEPATH "AArch64-capable llvm-strip" FORCE)
if(NOT DEFINED LLVM_DIR)
  set(LLVM_DIR "$shim_dir" CACHE PATH "Host LLVM executable shim")
endif()
if(NOT DEFINED Clang_DIR)
  set(Clang_DIR "$shim_dir" CACHE PATH "Host Clang executable shim")
endif()
EOF_CMAKE

  if [ "$CROSS_COMPILER" = clang ]; then
    cat >> "$tc_file" <<EOF_CMAKE

set(CMAKE_C_COMPILER "$host_clang")
set(CMAKE_CXX_COMPILER "$host_clangxx")
set(CMAKE_C_COMPILER_TARGET aarch64-linux-gnu)
set(CMAKE_CXX_COMPILER_TARGET aarch64-linux-gnu)
set(CMAKE_C_FLAGS_INIT "--gcc-install-dir=$gcc_dir")
set(CMAKE_CXX_FLAGS_INIT "--gcc-install-dir=$gcc_dir -stdlib=libstdc++")
set(CMAKE_EXE_LINKER_FLAGS_INIT "--gcc-install-dir=$gcc_dir -fuse-ld=lld -Wl,-rpath-link,$SYSROOT/lib/aarch64-linux-gnu:$SYSROOT/usr/lib/aarch64-linux-gnu:$TARGET_ROCM/lib")
set(CMAKE_SHARED_LINKER_FLAGS_INIT "--gcc-install-dir=$gcc_dir -fuse-ld=lld -Wl,-rpath-link,$SYSROOT/lib/aarch64-linux-gnu:$SYSROOT/usr/lib/aarch64-linux-gnu:$TARGET_ROCM/lib")
set(CMAKE_MODULE_LINKER_FLAGS_INIT "--gcc-install-dir=$gcc_dir -fuse-ld=lld -Wl,-rpath-link,$SYSROOT/lib/aarch64-linux-gnu:$SYSROOT/usr/lib/aarch64-linux-gnu:$TARGET_ROCM/lib")
EOF_CMAKE
  else
    local host_gcc host_gxx
    host_gcc=$(command -v aarch64-linux-gnu-gcc)
    host_gxx=$(command -v aarch64-linux-gnu-g++)
    cat >> "$tc_file" <<EOF_CMAKE

set(CMAKE_C_COMPILER "$host_gcc")
set(CMAKE_CXX_COMPILER "$host_gxx")
set(CMAKE_C_FLAGS_INIT "-B$gcc_dir")
set(CMAKE_CXX_FLAGS_INIT "-nostdinc++ -isystem $SYSROOT/usr/include/c++/13 -isystem $SYSROOT/usr/include/aarch64-linux-gnu/c++/13 -isystem $SYSROOT/usr/include/c++/13/backward -B$gcc_dir")
set(CMAKE_EXE_LINKER_FLAGS_INIT "-B$gcc_dir -L$gcc_dir -Wl,-rpath-link,$SYSROOT/lib/aarch64-linux-gnu:$SYSROOT/usr/lib/aarch64-linux-gnu:$TARGET_ROCM/lib")
set(CMAKE_SHARED_LINKER_FLAGS_INIT "-B$gcc_dir -L$gcc_dir -Wl,-rpath-link,$SYSROOT/lib/aarch64-linux-gnu:$SYSROOT/usr/lib/aarch64-linux-gnu:$TARGET_ROCM/lib")
set(CMAKE_MODULE_LINKER_FLAGS_INIT "-B$gcc_dir -L$gcc_dir -Wl,-rpath-link,$SYSROOT/lib/aarch64-linux-gnu:$SYSROOT/usr/lib/aarch64-linux-gnu:$TARGET_ROCM/lib")
EOF_CMAKE
  fi

  # A small C++ ABI canary is linked and checked before building ROCm sources.
  local canary_dir canary
  canary_dir="$BLD/abi-canary"
  mkdir -p "$canary_dir"
  cat > "$canary_dir/canary.cpp" <<'EOF_CPP'
#include <iostream>
#include <string>
int main() { std::string s = "Noble ABI"; std::cout << s << '\n'; }
EOF_CPP
  if [ "$CROSS_COMPILER" = clang ]; then
    clang++ --target=aarch64-linux-gnu --sysroot="$SYSROOT" --gcc-install-dir="$gcc_dir" \
      -stdlib=libstdc++ -fuse-ld=lld -std=c++17 "$canary_dir/canary.cpp" -o "$canary_dir/canary"
  else
    aarch64-linux-gnu-g++ --sysroot="$SYSROOT" -nostdinc++ \
      -isystem "$SYSROOT/usr/include/c++/13" \
      -isystem "$SYSROOT/usr/include/aarch64-linux-gnu/c++/13" \
      -isystem "$SYSROOT/usr/include/c++/13/backward" \
      -B"$gcc_dir" -L"$gcc_dir" -std=c++17 "$canary_dir/canary.cpp" -o "$canary_dir/canary"
  fi
  log "Toolchain generated: $tc_file"
  check_elf_tree "$canary_dir/canary"
}

clone_rocm_repo() {
  local repo=$1 dir="$SRC/$2" actual
  if [ -e "$dir" ] && [ ! -d "$dir/.git" ]; then die "Source path exists but is not a Git checkout: $dir"; fi
  if [ ! -d "$dir/.git" ]; then
    git clone --depth 1 --branch "$TAG" "https://github.com/ROCm/$repo.git" "$dir"
  fi
  actual=$(git -C "$dir" describe --tags --exact-match 2>/dev/null || true)
  [ "$actual" = "$TAG" ] || die "$dir is at tag '$actual', expected '$TAG'; refusing to build an unpinned source tree"
}

apply_patch_idempotent() {
  local dir=$1 patch_file=$2
  if git -C "$dir" apply --reverse --check "$patch_file" >/dev/null 2>&1; then
    log "Patch already applied: $(basename "$patch_file")"
  else
    git -C "$dir" apply --check "$patch_file" || die "Patch dry-run failed: $patch_file"
    git -C "$dir" apply "$patch_file"
    log "Applied patch: $(basename "$patch_file")"
  fi
}

stage_host_venv() {
  log "Preparing host Python build-helper venv"
  ensure_work_root_safe
  if [ ! -x "$HOST_VENV/bin/python" ]; then
    python3 -m venv "$HOST_VENV"
  fi
  "$HOST_VENV/bin/python" -c 'import yaml, msgpack, joblib, CppHeaderParser' >/dev/null 2>&1 || \
    "$HOST_VENV/bin/pip" install -q --upgrade pip pyyaml msgpack joblib CppHeaderParser
}

stage_fetch() {
  log "Fetching pinned ROCm $TAG source trees"
  ensure_work_root_safe
  clone_rocm_repo rocm-cmake rocm-cmake
  clone_rocm_repo llvm-project llvm-project
  clone_rocm_repo ROCR-Runtime ROCR-Runtime
  clone_rocm_repo rocminfo rocminfo
  apply_patch_idempotent "$SRC/rocminfo" "$REPO_ROOT/patches/0001-rocminfo-cross-system-processor.patch"
  apply_patch_idempotent "$SRC/ROCR-Runtime" "$REPO_ROOT/patches/0002-rocr-runtime-aarch64-intrinsics.patch"
  apply_patch_idempotent "$SRC/llvm-project" "$REPO_ROOT/patches/0003-device-libs-cmake4-cmp0053.patch"
}

stage_rocm_cmake() {
  log "Installing rocm-cmake ($TAG) to host and target prefixes"
  [ -d "$SRC/rocm-cmake/.git" ] || die "Run fetch stage first"
  local prefix
  for prefix in "$HOST_ROCM" "$TARGET_ROCM"; do
    cmake -S "$SRC/rocm-cmake" -B "$BLD/rocm-cmake" -G Ninja \
      -DCMAKE_BUILD_TYPE=Release \
      -DCMAKE_INSTALL_PREFIX="$prefix"
    cmake --build "$BLD/rocm-cmake" --parallel "$JOBS"
    cmake --install "$BLD/rocm-cmake"
  done
}

stage_host_llvm() {
  log "Building host ROCm LLVM/Clang/LLD (X86;AArch64;AMDGPU, LLVM_JOBS=$LLVM_JOBS, LINK_JOBS=$LINK_JOBS)"
  [ -d "$SRC/llvm-project/.git" ] || die "Run fetch stage first"
  local host_clang host_clangxx t
  host_clang=$(command -v clang)
  host_clangxx=$(command -v clang++)
  cmake -S "$SRC/llvm-project/llvm" -B "$BLD/host-llvm" -G Ninja \
    -DCMAKE_BUILD_TYPE=Release \
    -DCMAKE_C_COMPILER="$host_clang" \
    -DCMAKE_CXX_COMPILER="$host_clangxx" \
    -DCMAKE_CXX_FLAGS="-include cstdint" \
    -DCMAKE_INSTALL_PREFIX="$HOST_LLVM" \
    -DLLVM_TARGETS_TO_BUILD="X86;AArch64;AMDGPU" \
    -DLLVM_ENABLE_PROJECTS="clang;lld" \
    -DLLVM_ENABLE_ASSERTIONS=OFF \
    -DLLVM_INCLUDE_TESTS=OFF \
    -DLLVM_INCLUDE_BENCHMARKS=OFF \
    -DLLVM_INCLUDE_EXAMPLES=OFF \
    -DLLVM_INCLUDE_DOCS=OFF \
    -DLLVM_BUILD_DOCS=OFF \
    -DLLVM_ENABLE_TERMINFO=OFF \
    -DLLVM_ENABLE_LIBXML2=OFF \
    -DLLVM_ENABLE_LIBEDIT=OFF \
    -DLLVM_ENABLE_ZLIB=ON \
    -DLLVM_ENABLE_ZSTD=ON \
    -DLLVM_USE_LINKER=lld \
    -DLLVM_PARALLEL_LINK_JOBS="$LINK_JOBS"
  cmake --build "$BLD/host-llvm" --parallel "$LLVM_JOBS"
  cmake --install "$BLD/host-llvm"
  mkdir -p "$HOST_ROCM/bin" "$HOST_ROCM/lib"
  ln -sfn ../llvm "$HOST_ROCM/lib/llvm"
  for t in clang clang++; do
    ln -sf "$t" "$HOST_LLVM/bin/amd$t"
    ln -sf "$HOST_LLVM/bin/$t" "$HOST_ROCM/bin/amd$t"
  done
}

stage_device_libs() {
  log "Building ROCm Device Libs (AMDGCN bitcode)"
  [ -d "$SRC/llvm-project/.git" ] || die "Run fetch stage first"
  [ -x "$HOST_LLVM/bin/clang" ] || die "Run host_llvm stage first"
  [ -f "$HOST_ROCM/share/rocm/cmake/ROCMConfig.cmake" ] || die "Run rocm_cmake stage first"
  apply_patch_idempotent "$SRC/llvm-project" "$REPO_ROOT/patches/0003-device-libs-cmake4-cmp0053.patch"
  local host_clang host_clangxx
  host_clang=$(command -v clang)
  host_clangxx=$(command -v clang++)
  cmake -S "$SRC/llvm-project/amd/device-libs" -B "$BLD/device-libs" -G Ninja \
    -DCMAKE_BUILD_TYPE=Release \
    -DCMAKE_C_COMPILER="$host_clang" \
    -DCMAKE_CXX_COMPILER="$host_clangxx" \
    -DCMAKE_CXX_FLAGS="-include cstdint" \
    -DCMAKE_PREFIX_PATH="$HOST_LLVM;$HOST_ROCM" \
    -DCMAKE_INSTALL_PREFIX="$TARGET_ROCM"
  cmake --build "$BLD/device-libs" --parallel "$JOBS"
  cmake --install "$BLD/device-libs"
}

stage_rocr() {
  log "Cross-building ROCR Runtime"
  [ -f "$TOOLCHAIN_DIR/aarch64-noble-toolchain.cmake" ] || die "Run toolchain stage first"
  [ -d "$SRC/ROCR-Runtime/.git" ] || die "Run fetch stage first"
  cmake -S "$SRC/ROCR-Runtime" -B "$BLD/ROCR-Runtime" -G Ninja \
    -DCMAKE_BUILD_TYPE=Release \
    -DCMAKE_TOOLCHAIN_FILE="$TOOLCHAIN_DIR/aarch64-noble-toolchain.cmake" \
    -DCMAKE_INSTALL_PREFIX="$TARGET_ROCM" \
    -DCMAKE_INSTALL_RPATH=/opt/rocm/lib \
    -DLLVM_DIR="$TOOLCHAIN_DIR/host-llvm-cmake" \
    -DClang_DIR="$TOOLCHAIN_DIR/host-llvm-cmake" \
    -DIMAGE_SUPPORT=OFF \
    -DBUILD_SHARED_LIBS=ON \
    -DHSA_DEP_ROCPROFILER_REGISTER=OFF
  cmake --build "$BLD/ROCR-Runtime" --parallel "$JOBS"
  cmake --install "$BLD/ROCR-Runtime"
}

stage_rocminfo() {
  log "Cross-building rocminfo"
  [ -f "$TOOLCHAIN_DIR/aarch64-noble-toolchain.cmake" ] || die "Run toolchain stage first"
  [ -d "$SRC/rocminfo/.git" ] || die "Run fetch stage first"
  cmake -S "$SRC/rocminfo" -B "$BLD/rocminfo" -G Ninja \
    -DCMAKE_BUILD_TYPE=Release \
    -DROCRTST_BLD_TYPE=Release \
    -DCMAKE_TOOLCHAIN_FILE="$TOOLCHAIN_DIR/aarch64-noble-toolchain.cmake" \
    -DCMAKE_INSTALL_PREFIX="$TARGET_ROCM" \
    -DCMAKE_PREFIX_PATH="$TARGET_ROCM" \
    -Dhsa-runtime64_DIR="$TARGET_ROCM/lib/cmake/hsa-runtime64" \
    -DCMAKE_INSTALL_RPATH=/opt/rocm/lib
  cmake --build "$BLD/rocminfo" --parallel "$JOBS"
  cmake --install "$BLD/rocminfo"
}

check_elf_tree() {
  python3 - "$1" "$SYSROOT" "$TARGET_ROCM" <<'PY'
import os, re, subprocess, sys
scan = os.path.abspath(sys.argv[1])
sysroot = os.path.realpath(sys.argv[2])
target = os.path.realpath(sys.argv[3])
roots = (sysroot, target)
search = [
    os.path.join(target, 'lib'), os.path.join(target, 'lib64'),
    os.path.join(sysroot, 'lib/aarch64-linux-gnu'),
    os.path.join(sysroot, 'usr/lib/aarch64-linux-gnu'),
    os.path.join(sysroot, 'lib'), os.path.join(sysroot, 'usr/lib'),
]
limits = {'GLIBC': (2, 39), 'GLIBCXX': (3, 4, 32), 'CXXABI': (1, 3, 14)}

def readelf(*args):
    return subprocess.check_output(['readelf', *args], text=True, stderr=subprocess.STDOUT)

def inside(path):
    real = os.path.realpath(path)
    return any(os.path.commonpath((real, root)) == root for root in roots)

def version_tuple(value):
    return tuple(int(part) for part in value.split('.'))

def resolve(soname):
    for directory in search:
        candidate = os.path.join(directory, soname)
        if not os.path.lexists(candidate):
            continue
        real = os.path.realpath(candidate)
        if inside(real) and os.path.isfile(real):
            return real
    return None

def check_one(path, seen, allow_entry=False):
    path = os.path.realpath(path)
    if not allow_entry and not inside(path):
        raise RuntimeError(f'object escaped target/sysroot roots: {path}')
    header = readelf('-h', path)
    if 'ELF64' not in header or 'AArch64' not in header:
        raise RuntimeError(f'{path}: expected ELF64 AArch64')
    in_sysroot = os.path.commonpath((path, sysroot)) == sysroot
    if not in_sysroot:
        versions = readelf('-V', path)
        needs_section = versions.split("Version definition section", 1)[0]
        if "Version needs section" in versions:
            needs_section = versions.split("Version needs section", 1)[1].split("Version definition section", 1)[0]
        for namespace, ceiling in limits.items():
            for match in re.finditer(rf'\b{namespace}_(\d+(?:\.\d+)*)\b', needs_section):
                found = version_tuple(match.group(1))
                if found > ceiling:
                    raise RuntimeError(f'{path}: {namespace}_{match.group(1)} exceeds Noble ceiling {ceiling}')
    dynamic = readelf('-d', path)
    for line in dynamic.splitlines():
        if '(RPATH)' in line or '(RUNPATH)' in line:
            match = re.search(r'\[(.*?)\]', line)
            if match and any(bad in match.group(1) for bad in ('/home/', '/run/media/', '/usr/lib/x86_64')):
                raise RuntimeError(f'{path}: build-host path leaked into {line.strip()}')
        if '(NEEDED)' in line:
            match = re.search(r'Shared library: \[([^]]+)\]', line)
            if match:
                dep = resolve(match.group(1))
                if dep is None:
                    raise RuntimeError(f'{path}: DT_NEEDED {match.group(1)} not found inside target/sysroot roots')
                if dep not in seen:
                    seen.add(dep)
                    check_one(dep, seen)

if os.path.isfile(scan):
    candidates = [scan]
else:
    candidates = []
    for directory, _, files in os.walk(scan):
        for name in files:
            path = os.path.join(directory, name)
            if os.path.islink(path):
                continue
            try:
                with open(path, 'rb') as stream:
                    if stream.read(4) == b'\x7fELF':
                        candidates.append(path)
            except OSError:
                pass
if not candidates:
    raise RuntimeError(f'no ELF files found under {scan}')
seen = set(os.path.realpath(path) for path in candidates)
allow_top = os.path.isfile(scan)
for path in candidates:
    check_one(path, seen, allow_entry=allow_top)
print(f'ELF verification passed: {len(candidates)} installed ELF object(s); {len(seen)} total ELF objects including recursively resolved dependencies')
PY
}

stage_verify() {
  log "Verifying ARM64 ELF, dependency closure, Noble ABI ceilings and QEMU startup"
  [ -x "$TARGET_ROCM/bin/rocminfo" ] || die "Missing $TARGET_ROCM/bin/rocminfo"
  [ -x "$TARGET_ROCM/bin/rocm_agent_enumerator" ] || die "Missing $TARGET_ROCM/bin/rocm_agent_enumerator"
  check_elf_tree "$TARGET_ROCM"
  if [ "$SKIP_QEMU_SMOKE" = 1 ]; then
    log "SKIP_QEMU_SMOKE=1; QEMU run skipped"
    return
  fi

  local qemu output rc ldpath
  qemu=$(find_qemu) || die "QEMU AArch64 user emulator not found"
  ldpath="$TARGET_ROCM/lib:$SYSROOT/lib/aarch64-linux-gnu:$SYSROOT/usr/lib/aarch64-linux-gnu"
  set +e
  output=$(env -u LD_PRELOAD QEMU_LD_PREFIX="$SYSROOT" LD_LIBRARY_PATH="$ldpath" "$qemu" "$TARGET_ROCM/bin/rocminfo" 2>&1)
  rc=$?
  set -e
  printf '%s\n' "$output"
  if printf '%s\n' "$output" | grep -qiE 'error while loading shared libraries|cannot open shared object file|version .*(GLIBC|GLIBCXX)_'; then
    die "QEMU reported a target dynamic-loader or symbol-version failure"
  fi
  [ "$rc" -lt 128 ] || die "QEMU rocminfo crashed (exit $rc)"
  if [ "$rc" -eq 0 ] && printf '%s\n' "$output" | grep -q 'HSA Agents'; then
    log "QEMU rocminfo startup passed (HSA Agents reported)"
  elif [ "$rc" -eq 1 ] && printf '%s\n' "$output" | grep -qE 'Unable to open /dev/kfd read-write:|ROCk module is NOT loaded'; then
    log "QEMU rocminfo startup passed; expected no-KFD diagnostic received"
  elif [ "$rc" -eq 8 ] \
    && [ -r /dev/kfd ] && [ -w /dev/kfd ] && [ -e /sys/module/amdgpu/initstate ] \
    && printf '%s\n' "$output" | grep -q 'ROCk module is loaded' \
    && printf '%s\n' "$output" | grep -q 'HSA_STATUS_ERROR_OUT_OF_RESOURCES'; then
    local strace_out
    strace_out=$(env -u LD_PRELOAD QEMU_LD_PREFIX="$SYSROOT" LD_LIBRARY_PATH="$ldpath" "$qemu" -strace "$TARGET_ROCM/bin/rocminfo" 2>&1 || true)
    if printf '%s\n' "$strace_out" | grep -qE 'openat\(.*"/dev/kfd",.*\) = [0-9]+' \
      && printf '%s\n' "$strace_out" | grep -qE 'ioctl\([0-9]+,\s*(0x80084b01|AMDKFD_IOC_GET_VERSION),.*\) = -1 errno=25\b'; then
      log "QEMU rocminfo startup passed (reached HSA/libhsakmt KFD init; AMDKFD_IOC_GET_VERSION ioctl 0x80084b01 is unemulated by qemu-user: ENOTTY)"
    else
      die "QEMU rocminfo failed with HSA_STATUS_ERROR_OUT_OF_RESOURCES without matching unemulated KFD ioctl ENOTTY"
    fi
  else
    die "Unexpected QEMU result (exit $rc); expected HSA Agents, known no-KFD diagnostic, or unemulated KFD ioctl ENOTTY"
  fi
}

run_stage() {
  case "$1" in
    preflight) stage_preflight ;;
    sysroot) stage_sysroot ;;
    toolchain) stage_toolchain ;;
    host_venv) stage_host_venv ;;
    fetch) stage_fetch ;;
    rocm_cmake) stage_rocm_cmake ;;
    host_llvm) stage_host_llvm ;;
    device_libs) stage_device_libs ;;
    rocr) stage_rocr ;;
    rocminfo) stage_rocminfo ;;
    verify) stage_verify ;;
    *) die "Unknown stage '$1' (valid: ${STAGES[*]})" ;;
  esac
}

main() {
  local mode=from start=preflight only= arg started=0 stage
  while [ "$#" -gt 0 ]; do
    arg=$1; shift
    case "$arg" in
      --list) printf '%s\n' "${STAGES[@]}"; return 0 ;;
      --only) [ "$#" -gt 0 ] || die "--only requires a stage"; mode=only; only=$1; shift ;;
      -h|--help) usage; return 0 ;;
      *) start=$arg ;;
    esac
  done
  if [ "$mode" = only ]; then run_stage "$only"; return 0; fi
  for stage in "${STAGES[@]}"; do
    [ "$stage" = "$start" ] && started=1
    [ "$started" -eq 1 ] && run_stage "$stage"
  done
  [ "$started" -eq 1 ] || die "Unknown start stage '$start'"
}

main "$@"
